window.GUIDES=[{"id":"running-sinker","title":"Running sinker rig","for":["bream","flathead","whiting","snapper"],"intro":"The best all-round bait rig. The sinker slides, so a fish can take the bait without feeling the weight.","you_need":"Small ball sinker, swivel, 50 cm of leader line, size 4 to 1 hook, bait.","steps":["Thread the ball sinker onto your main line.","Tie the main line to one end of the swivel (improved clinch knot).","Tie about 50 cm of leader to the other end of the swivel.","Tie the hook to the end of the leader.","Hide the hook point inside the bait, cast out and let it sink to the bottom.","Keep the line just tight. When you feel taps, lift the rod firmly."],"kid_tip":"Watch the rod tip. Little taps mean a fish is nibbling. Wait for a strong pull!","safety":"Point the rod tip away from people when you cast, and look behind you first.","video":{"label":"Running rigs guide (Black Magic Tackle)","url":"https://blackmagictackle.com/fishing-guides/running-rigs"},"yt":"https://www.youtube.com/results?search_query=how+to+tie+a+running+sinker+rig+for+bream","draw":[["rect",0,40,320,160,{"fill":"#DCEDEE"}],["path",[["M",0,40],["C",20,35,40,45,60,40],["C",80,35,100,45,120,40],["C",140,35,160,45,180,40],["C",200,35,220,45,240,40],["C",260,35,280,45,300,40],["L",320,40]],{"stroke":"#13707A","w":1.5}],["rect",0,185,320,15,{"fill":"#EAD9B5"}],["line",0,20,140,120,{"c":"#2E3A8C","w":2}],["text",20,14,"Main line",{"size":10,"anchor":"start","c":"#56696D","bold":false}],["circle",120,106,9,{"fill":"#7F8C8D","stroke":"#10262B","w":1.5}],["text",108,128,"Ball sinker (slides)",{"size":9,"anchor":"end","c":"#56696D","bold":false}],["circle",146,128,4,{"fill":"none","stroke":"#10262B","w":2}],["rect",150,125,4,6,{"fill":"#10262B"}],["circle",158,128,4,{"fill":"none","stroke":"#10262B","w":2}],["text",152,150,"Swivel",{"size":9,"anchor":"middle","c":"#56696D","bold":false}],["line",158,128,250,150,{"c":"#13707A","w":1.6,"dash":true}],["text",214,128,"Leader 50 cm",{"size":9,"anchor":"middle","c":"#13707A","bold":false}],["circle",252.0,148.0,3.0,{"fill":"none","stroke":"#10262B","w":2}],["path",[["M",252.0,151.0],["L",252.0,174.0],["C",252.0,186.0,266.0,186.0,266.0,174.0],["L",266.0,168.0]],{"stroke":"#10262B","w":2.4}],["poly",[[266.0,166.0],[263.0,172.0],[269.0,172.0]],{"fill":"#10262B"}],["path",[["M",262,170],["C",272,158,292,160,296,172],["C",288,178,272,178,262,170]],{"fill":"#F2A27A","stroke":"#10262B","w":1.5}],["line",292,166,306,158,{"c":"#10262B","w":1}],["line",292,168,308,166,{"c":"#10262B","w":1}],["text",262,116,"Hook + bait",{"size":9,"anchor":"middle","c":"#56696D","bold":false}]],"pdf":"guides/running-sinker.pdf"},{"id":"paternoster","title":"Paternoster rig","for":["leatherjacket","trevally","bream","snapper"],"intro":"Two hooks above a sinker. Great off wharves and rocks because the baits sit up off the bottom, away from snags.","you_need":"Bomb sinker, 1 m of leader line, two small long-shank hooks (size 8 to 4), bait.","steps":["Tie a dropper loop about 30 cm from the end of the leader, and another 30 cm above it.","Tie the bomb sinker to the very end of the leader.","Thread a hook onto each loop (pass the loop through the hook eye and over the hook).","Tie the top of the leader to your main line with a swivel.","Lower it straight down beside the pylons until the sinker touches bottom, then wind in a little.","Strike quickly. Leatherjackets are fast nibblers!"],"kid_tip":"Drop it straight down next to the wharf. No big cast needed!","safety":"Hold onto the rail and never lean over the edge of a wharf.","video":{"label":"How to tie a paternoster rig with Paul Worsteling (Club Marine)","url":"https://www.clubmarine.com.au/explore-boating/videos/how-to-tie-a-paternoster-rig.html"},"yt":"https://www.youtube.com/results?search_query=how+to+tie+a+paternoster+rig+dropper+loop","draw":[["rect",0,30,320,170,{"fill":"#DCEDEE"}],["path",[["M",0,30],["C",20,25,40,35,60,30],["C",80,25,100,35,120,30],["C",140,25,160,35,180,30],["C",200,25,220,35,240,30],["C",260,25,280,35,300,30],["L",320,30]],{"stroke":"#13707A","w":1.5}],["rect",0,185,320,15,{"fill":"#EAD9B5"}],["rect",30,0,26,200,{"fill":"#9AA7AA"}],["text",43,196,"Pylon",{"size":9,"anchor":"middle","c":"#FFFFFF","bold":false}],["line",160,0,160,165,{"c":"#2E3A8C","w":2}],["circle",154,46,4,{"fill":"none","stroke":"#10262B","w":2}],["rect",158,43,4,6,{"fill":"#10262B"}],["circle",166,46,4,{"fill":"none","stroke":"#10262B","w":2}],["text",178,50,"Swivel",{"size":9,"anchor":"start","c":"#56696D","bold":false}],["path",[["M",160,80],["C",176,76,190,84,160,90]],{"stroke":"#2E3A8C","w":2}],["circle",186.0,84.0,2.4000000000000004,{"fill":"none","stroke":"#10262B","w":2}],["path",[["M",186.0,86.4],["L",186.0,104.8],["C",186.0,114.4,197.2,114.4,197.2,104.8],["L",197.2,100.0]],{"stroke":"#10262B","w":2.4}],["poly",[[197.2,98.4],[194.8,103.2],[199.6,103.2]],{"fill":"#10262B"}],["text",212,98,"Dropper loop + hook",{"size":9,"anchor":"start","c":"#56696D","bold":false}],["path",[["M",160,120],["C",176,116,190,124,160,130]],{"stroke":"#2E3A8C","w":2}],["circle",186.0,124.0,2.4000000000000004,{"fill":"none","stroke":"#10262B","w":2}],["path",[["M",186.0,126.4],["L",186.0,144.8],["C",186.0,154.4,197.2,154.4,197.2,144.8],["L",197.2,140.0]],{"stroke":"#10262B","w":2.4}],["poly",[[197.2,138.4],[194.8,143.2],[199.6,143.2]],{"fill":"#10262B"}],["poly",[[152,165],[168,165],[164,184],[156,184]],{"fill":"#7F8C8D","stroke":"#10262B","w":1.5}],["text",178,178,"Bomb sinker",{"size":9,"anchor":"start","c":"#56696D","bold":false}]],"pdf":"guides/paternoster.pdf"},{"id":"unweighted","title":"Unweighted bait rig","for":["bream","mullet","luderick","trevally","snapper"],"intro":"The simplest rig there is: just a hook and bait. It drifts down slowly and naturally, which fussy fish love.","you_need":"Small hook (size 10 to 4), light line, bread or a small piece of prawn. Optional: a small float.","steps":["Tie the hook straight onto the end of your line.","Squeeze a small piece of bread or prawn onto the hook so the point is covered.","Flick it out gently. There's no sinker, so it doesn't need to go far.","Let it sink slowly. Throw a few crumbs in the water nearby to attract fish.","For luderick or mullet, clip on a small float so you can see bites.","When the float dips or the line moves off, lift the rod."],"kid_tip":"Best rig for first-timers. Bread and a tiny hook catch mullet almost anywhere!","safety":"Keep the hook covered or in a cork when you're not fishing.","video":null,"yt":"https://www.youtube.com/results?search_query=unweighted+bait+fishing+for+bream+beginners","draw":[["rect",0,50,320,150,{"fill":"#DCEDEE"}],["path",[["M",0,50],["C",20,45,40,55,60,50],["C",80,45,100,55,120,50],["C",140,45,160,55,180,50],["C",200,45,220,55,240,50],["C",260,45,280,55,300,50],["L",320,50]],{"stroke":"#13707A","w":1.5}],["path",[["M",10,10],["C",80,20,140,40,170,60]],{"stroke":"#2E3A8C","w":2}],["text",12,26,"Line",{"size":10,"anchor":"start","c":"#56696D","bold":false}],["ellipse",172,56,7,11,{"fill":"#E5533D","stroke":"#10262B","w":1.5}],["text",190,42,"Optional float",{"size":9,"anchor":"start","c":"#56696D","bold":false}],["line",172,67,190,130,{"c":"#2E3A8C","w":1.6}],["circle",190.0,130.0,3.0,{"fill":"none","stroke":"#10262B","w":2}],["path",[["M",190.0,133.0],["L",190.0,156.0],["C",190.0,168.0,204.0,168.0,204.0,156.0],["L",204.0,150.0]],{"stroke":"#10262B","w":2.4}],["poly",[[204.0,148.0],[201.0,154.0],[207.0,154.0]],{"fill":"#10262B"}],["circle",202,160,9,{"fill":"#F6E3B4","stroke":"#10262B","w":1.5}],["text",220,164,"Bread or prawn",{"size":9,"anchor":"start","c":"#56696D","bold":false}],["circle",120,90,2.5,{"fill":"#F6E3B4"}],["circle",130,110,2.5,{"fill":"#F6E3B4"}],["circle",112,126,2.5,{"fill":"#F6E3B4"}],["text",80,150,"Crumbs attract fish",{"size":9,"anchor":"middle","c":"#56696D","bold":false}]],"pdf":"guides/unweighted.pdf"},{"id":"soft-plastic","title":"Soft plastic on a jighead","for":["flathead","bream","kingfish","tailor"],"intro":"A rubbery lure on a weighted hook. No bait needed. Hop it along the bottom and flathead can't resist.","you_need":"Jighead (1/8 to 1/4 oz, hook size 1/0 to 2/0), 3 to 4 inch soft plastic, leader line.","steps":["Tie the jighead to your leader with a uni knot.","Push the hook point into the very front of the plastic.","Slide the plastic up the hook, then push the point out through the top so the lure sits straight.","Cast out and count while it sinks until the line goes slack (it's on the bottom).","Give the rod two sharp lifts, then let the lure sink back down on a tight line.","Most bites come as it sinks. If the line twitches, strike!"],"kid_tip":"Lift, lift, drop. Lift, lift, drop. Pretend your lure is a little fish hopping along.","safety":"Jigheads are sharp and heavy. Cast overhead, never sideways near people.","video":{"label":"How to catch flathead on soft plastics (Shimano)","url":"https://fish.shimano.com/en-AU/content/c/Articles/how-to/how-to-catch-flathead-on-soft-plastics0.html"},"yt":"https://www.youtube.com/results?search_query=how+to+rig+a+soft+plastic+on+a+jighead","draw":[["rect",0,20,320,180,{"fill":"#DCEDEE"}],["path",[["M",0,20],["C",20,15,40,25,60,20],["C",80,15,100,25,120,20],["C",140,15,160,25,180,20],["C",200,15,220,25,240,20],["C",260,15,280,25,300,20],["L",320,20]],{"stroke":"#13707A","w":1.5}],["rect",0,175,320,25,{"fill":"#EAD9B5"}],["path",[["M",20,170],["C",40,120,60,120,80,170],["C",100,120,120,120,140,170],["C",160,120,180,120,200,170]],{"stroke":"#B9752A","w":1.6,"dash":true}],["text",110,112,"Lift, lift... drop",{"size":10,"anchor":"middle","c":"#B9752A","bold":true}],["circle",240,150,9,{"fill":"#E0A21B","stroke":"#10262B","w":1.5}],["path",[["M",248,146],["C",270,140,290,146,304,140],["C",296,150,280,156,248,156]],{"fill":"#3BB273","stroke":"#10262B","w":1.5}],["path",[["M",266,144],["L",266,134]],{"stroke":"#10262B","w":2}],["text",240,132,"Jighead",{"size":9,"anchor":"middle","c":"#56696D","bold":false}],["text",290,172,"Soft plastic",{"size":9,"anchor":"middle","c":"#56696D","bold":false}],["line",230,146,160,20,{"c":"#2E3A8C","w":1.6}],["text",205,70,"Leader",{"size":9,"anchor":"start","c":"#56696D","bold":false}]],"pdf":"guides/soft-plastic.pdf"},{"id":"knots","title":"Two knots to know","for":["bream","flathead","tailor","kingfish","whiting"],"intro":"Almost every rig uses one of these. Practise at home with thick string first.","you_need":"Line, a hook or swivel, and a bit of spit or water to wet the knot.","steps":["Improved clinch knot: thread the line through the hook eye and pull 15 cm through.","Twist the end around the main line 5 to 7 times.","Push the end back through the small loop next to the eye, then through the big loop you just made.","Wet the knot, pull the main line tight and trim the end.","Uni knot: thread the line through the eye, lay the end back alongside the line to make a loop, and wrap the end around both lines and through the loop 5 times.","Wet it, pull the end to snug the wraps, then pull the main line to slide the knot down to the eye. Trim."],"kid_tip":"Always wet the knot before pulling tight. Dry knots get hot and weak.","safety":"Use nail clippers, not your teeth, to trim line.","video":{"label":"Improved clinch knot with Barry Stokes (Mercury)","url":"https://www.mercurymarine.com/sp/en/lifestyle/dockline/how-to-tie-the-improved-clinch-knot-with-barry-stokes"},"yt":"https://www.youtube.com/results?search_query=how+to+tie+a+uni+knot+fishing","draw":[["text",80,18,"Improved clinch knot",{"size":11,"anchor":"middle","c":"#10262B","bold":true}],["text",240,18,"Uni knot",{"size":11,"anchor":"middle","c":"#10262B","bold":true}],["line",160,30,160,190,{"c":"#D3E0DF","w":1}],["circle",110.0,70.0,6.0,{"fill":"none","stroke":"#10262B","w":2}],["path",[["M",110.0,76.0],["L",110.0,122.0],["C",110.0,146.0,138.0,146.0,138.0,122.0],["L",138.0,110.0]],{"stroke":"#10262B","w":2.4}],["poly",[[138.0,106.0],[132.0,118.0],[144.0,118.0]],{"fill":"#10262B"}],["line",10,70,100,70,{"c":"#2E3A8C","w":2}],["ellipse",30,70,5,8,{"fill":"none","stroke":"#2E3A8C","w":1.6}],["ellipse",41,70,5,8,{"fill":"none","stroke":"#2E3A8C","w":1.6}],["ellipse",52,70,5,8,{"fill":"none","stroke":"#2E3A8C","w":1.6}],["ellipse",63,70,5,8,{"fill":"none","stroke":"#2E3A8C","w":1.6}],["ellipse",74,70,5,8,{"fill":"none","stroke":"#2E3A8C","w":1.6}],["ellipse",85,70,5,8,{"fill":"none","stroke":"#2E3A8C","w":1.6}],["path",[["M",104,72],["C",100,92,40,92,30,78]],{"stroke":"#2E3A8C","w":1.6}],["text",60,110,"5 to 7 twists",{"size":9,"anchor":"middle","c":"#56696D","bold":false}],["circle",270.0,70.0,6.0,{"fill":"none","stroke":"#10262B","w":2}],["path",[["M",270.0,76.0],["L",270.0,122.0],["C",270.0,146.0,298.0,146.0,298.0,122.0],["L",298.0,110.0]],{"stroke":"#10262B","w":2.4}],["poly",[[298.0,106.0],[292.0,118.0],[304.0,118.0]],{"fill":"#10262B"}],["line",170,70,260,70,{"c":"#2E3A8C","w":2}],["path",[["M",266,72],["C",240,100,200,100,190,74]],{"stroke":"#2E3A8C","w":1.6}],["ellipse",200,76,5,9,{"fill":"none","stroke":"#2E3A8C","w":1.6}],["ellipse",210,76,5,9,{"fill":"none","stroke":"#2E3A8C","w":1.6}],["ellipse",220,76,5,9,{"fill":"none","stroke":"#2E3A8C","w":1.6}],["ellipse",230,76,5,9,{"fill":"none","stroke":"#2E3A8C","w":1.6}],["ellipse",240,76,5,9,{"fill":"none","stroke":"#2E3A8C","w":1.6}],["text",215,130,"5 wraps through the loop",{"size":9,"anchor":"middle","c":"#56696D","bold":false}],["text",160,186,"Wet it, pull tight, trim the end",{"size":10,"anchor":"middle","c":"#13707A","bold":true}]],"pdf":"guides/knots.pdf"},{"id":"bait","title":"Bait guide","for":["bream","flathead","whiting","mullet","luderick","snapper"],"intro":"Fresh bait catches more fish. Match the bait to the fish you want.","you_need":"A small esky or bucket to keep bait cool, a bait board and a knife (grown-ups only).","steps":["Prawns (raw, peeled): bream, whiting, flathead, trevally. Thread a whole small prawn onto the hook.","Squid strips: flathead, snapper, tailor, leatherjacket. Cut thin strips about finger length.","Pippies or worms: whiting and bream on sand. Soft, so cover the hook gently.","Bread or dough: mullet, bream and luderick. Pinch a pea-sized piece onto a tiny hook.","Green weed or cabbage: luderick. Wrap a small strand around the hook under a float.","Pilchards: tailor, kingfish and flathead. Use half a pilchard on a bigger hook."],"kid_tip":"Small bait, small hook. Most harbour fish have little mouths!","safety":"Keep bait out of the sun and take leftovers home. Don't feed birds.","video":null,"yt":"https://www.youtube.com/results?search_query=best+baits+for+bream+flathead+whiting+australia","draw":[["path",[["M",20,60],["C",30,48,50,50,54,62],["C",46,68,30,68,20,60]],{"fill":"#F2A27A","stroke":"#10262B","w":1.5}],["line",50,56,64,48,{"c":"#10262B","w":1}],["line",50,58,66,56,{"c":"#10262B","w":1}],["text",40,90,"Prawn",{"size":10,"anchor":"middle","c":"#10262B","bold":true}],["rect",110,50,60,14,{"fill":"#F7E9F0","stroke":"#10262B","w":1.5}],["text",140,90,"Squid strip",{"size":10,"anchor":"middle","c":"#10262B","bold":true}],["ellipse",240,56,22,12,{"fill":"#F6E3B4","stroke":"#10262B","w":1.5}],["path",[["M",222,56],["C",232,50,248,50,258,56]],{"stroke":"#10262B","w":1}],["text",240,90,"Pippi",{"size":10,"anchor":"middle","c":"#10262B","bold":true}],["circle",40,140,12,{"fill":"#FFF7E0","stroke":"#10262B","w":1.5}],["text",40,176,"Bread",{"size":10,"anchor":"middle","c":"#10262B","bold":true}],["path",[["M",110,140],["C",125,120,140,160,155,135],["C",160,128,168,150,172,140]],{"stroke":"#3BB273","w":4}],["text",140,176,"Green weed",{"size":10,"anchor":"middle","c":"#10262B","bold":true}],["path",[["M",210,140],["C",230,126,260,126,270,140],["C",260,152,230,152,210,140]],{"fill":"#B8C4C6","stroke":"#10262B","w":1.5}],["poly",[[270,140],[280,132],[280,148]],{"fill":"#B8C4C6","stroke":"#10262B","w":1.5}],["text",245,176,"Pilchard",{"size":10,"anchor":"middle","c":"#10262B","bold":true}]],"pdf":"guides/bait.pdf"},{"id":"squid-jig","title":"Squid jigging","for":["squid"],"intro":"Squid hunt by sight, so calm, clear water is best, especially at dawn, dusk and under wharf lights at night.","you_need":"Size 2.0 to 3.0 squid jig, light rod, bucket for the squid (they squirt ink!).","steps":["Tie the jig straight to your line with an improved clinch knot or a small snap.","Cast out near weed beds or the edge of wharf lights.","Count to 10 while it sinks (longer in deeper water).","Give the rod two gentle lifts, then let the jig sink again on a slack line.","Squid grab the jig as it sinks. When it feels heavy, wind smoothly. Don't jerk.","Lift the squid out pointing away from you and drop it into the bucket."],"kid_tip":"Squid squirt ink when they're lifted out. Point them away from your clothes!","safety":"Squid jig hooks are very sharp: hold the jig by its body, not the spikes.","video":null,"yt":"https://www.youtube.com/results?search_query=how+to+catch+squid+from+a+wharf+squid+jig+beginners","draw":[["rect",0,20,320,180,{"fill":"#DCEDEE"}],["path",[["M",0,20],["C",20,15,40,25,60,20],["C",80,15,100,25,120,20],["C",140,15,160,25,180,20],["C",200,15,220,25,240,20],["C",260,15,280,25,300,20],["L",320,20]],{"stroke":"#13707A","w":1.5}],["rect",0,185,320,15,{"fill":"#EAD9B5"}],["path",[["M",30,185],["C",26,160,36,150,30,130],["M",44,185],["C",48,165,40,150,46,138],["M",58,185],["C",54,168,62,156,58,144]],{"stroke":"#3BB273","w":3}],["text",46,120,"Weed bed",{"size":9,"anchor":"middle","c":"#56696D","bold":false}],["path",[["M",150,30],["L",150,110]],{"stroke":"#B9752A","w":1.6,"dash":true}],["text",158,70,"Count to 10 as it sinks",{"size":9,"anchor":"start","c":"#B9752A","bold":true}],["path",[["M",140,120],["C",150,100,170,100,180,120]],{"stroke":"#B9752A","w":1.6,"dash":true}],["text",178,104,"Two gentle lifts",{"size":9,"anchor":"start","c":"#B9752A","bold":true}],["path",[["M",200,130],["C",220,122,250,122,262,130],["C",250,138,220,138,200,130]],{"fill":"#E5533D","stroke":"#10262B","w":1.5}],["line",262,126,270,120,{"c":"#10262B","w":1.5}],["line",262,130,272,130,{"c":"#10262B","w":1.5}],["line",262,134,270,140,{"c":"#10262B","w":1.5}],["text",232,152,"Squid jig",{"size":9,"anchor":"middle","c":"#56696D","bold":false}]],"pdf":"guides/squid-jig.pdf"},{"id":"release","title":"Handling and releasing fish","for":["bream","flathead","tailor","kingfish","snapper","whiting"],"intro":"Undersize fish, oversize flathead and everything caught west of the Harbour Bridge goes back. Do it gently and quickly.","you_need":"Wet hands or a wet towel, long-nose pliers, a ruler or measuring sticker on your rod.","steps":["Wet your hands before touching the fish. Dry hands rub off their protective slime.","Hold the fish gently: one hand under the belly, one near the tail. Never squeeze.","Keep it in or over the water as much as you can. Lay it on a wet surface to measure, never on hot concrete.","Use pliers to back the hook out. If it's swallowed deep, cut the line close to the mouth instead.","Hold it upright in the water, facing into the current, until it swims off by itself.","Watch out for spines (flathead, leatherjacket) and teeth (tailor, kingfish)."],"kid_tip":"Be quick and gentle. Count to 30: the fish should be back in the water before you finish!","safety":"Flathead have sharp spikes on the sides of their head. Hold them from behind with a wet towel.","video":{"label":"Catch and release tips (NSW DPI)","url":"https://www.dpi.nsw.gov.au/dpi/fishing/recreational-fishing/responsible-fishing/catch-and-release"},"yt":"https://www.youtube.com/results?search_query=how+to+release+a+fish+safely","draw":[["rect",0,120,320,80,{"fill":"#DCEDEE"}],["path",[["M",0,120],["C",20,115,40,125,60,120],["C",80,115,100,125,120,120],["C",140,115,160,125,180,120],["C",200,115,220,125,240,120],["C",260,115,280,125,300,120],["L",320,120]],{"stroke":"#13707A","w":1.5}],["ellipse",160,90,70,26,{"fill":"#B8C4C6","stroke":"#10262B","w":2}],["poly",[[228,90],[260,66],[260,114]],{"fill":"#B8C4C6","stroke":"#10262B","w":2}],["circle",108,84,4,{"fill":"#10262B"}],["path",[["M",120,130],["C",130,112,170,112,180,130]],{"fill":"#F2C9A6","stroke":"#10262B","w":1.5}],["text",150,150,"Support the belly",{"size":9,"anchor":"middle","c":"#10262B","bold":true}],["path",[["M",215,128],["C",220,108,245,108,248,126]],{"fill":"#F2C9A6","stroke":"#10262B","w":1.5}],["text",240,150,"Hold near the tail",{"size":9,"anchor":"middle","c":"#10262B","bold":true}],["text",160,40,"Wet hands, gentle grip, back in quickly",{"size":11,"anchor":"middle","c":"#13707A","bold":true}],["path",[["M",40,175],["L",80,175]],{"stroke":"#13707A","w":2}],["poly",[[80,170],[90,175],[80,180]],{"fill":"#13707A"}],["text",65,192,"Face into the current",{"size":9,"anchor":"middle","c":"#56696D","bold":false}]],"pdf":"guides/release.pdf"}];
